import { Close } from "@mui/icons-material";
import {
  Box,
  Drawer,
  IconButton,
  List,
  ListItem,
  ListItemText,
  Tab,
  Tabs,
  Toolbar,
  useMediaQuery,
  useTheme,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Rating,
  Button,
  Typography,
  Avatar,
  GlobalStyles,
  Snackbar,
  Alert
} from "@mui/material";
import { useState } from "react";
import { FaTableTennis } from "react-icons/fa";
import { GiHamburgerMenu } from "react-icons/gi";
import CustomButton from "../Components/CustomButton";

// Your Google Apps Script Web App URL
const GOOGLE_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbzQ9ec_uyZ9YEuZc97X6RDudB0CfTChKEXsyI20Ax5HWqHPluW6k0uvA0IOzas-DExJ/exec';

const NavBar = () => {
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [currentTab, setCurrentTab] = useState(0);
  const [reviewDialogOpen, setReviewDialogOpen] = useState(false);
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });
  const [reviewData, setReviewData] = useState({
    name: "",
    photo: null,
    feedback: "",
    rating: 0,
    additionalPhotos: []
  });
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));

  const menuItems = ["Home", "About", "Testimonials", "Gallery and Awards"];

  const showSnackbar = (message, severity = 'success') => {
    setSnackbar({ open: true, message, severity });
  };

  const handleDrawerToggle = () => {
    setDrawerOpen(!drawerOpen);
  };

  const handleTabChange = (event, newValue) => {
    setCurrentTab(newValue);
    console.log("Navigating to:", menuItems[newValue]);
  };

  const handleMobileMenuItemClick = (index) => {
    setCurrentTab(index);
    setDrawerOpen(false);
    console.log("Navigating to:", menuItems[index]);
  };

  const handleReviewDialogOpen = () => {
    setReviewDialogOpen(true);
  };

  const handleReviewDialogClose = () => {
    setReviewDialogOpen(false);
    setReviewData({
      name: "",
      photo: null,
      feedback: "",
      rating: 0,
      additionalPhotos: []
    });
  };

  const handleInputChange = (field, value) => {
    setReviewData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handlePhotoUpload = (event, field) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setReviewData(prev => ({
          ...prev,
          [field]: e.target.result
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAdditionalPhotosUpload = (event) => {
    const files = Array.from(event.target.files);
    if (files.length > 0) {
      const newPhotos = [];
      files.forEach(file => {
        const reader = new FileReader();
        reader.onload = (e) => {
          newPhotos.push(e.target.result);
          if (newPhotos.length === files.length) {
            setReviewData(prev => ({
              ...prev,
              additionalPhotos: [...prev.additionalPhotos, ...newPhotos]
            }));
          }
        };
        reader.readAsDataURL(file);
      });
    }
  };

  const handleSubmitReview = async () => {
    // Validate mandatory fields
    if (!reviewData.name.trim() || !reviewData.feedback.trim() || reviewData.rating === 0) {
      showSnackbar('Please fill all mandatory fields: Name, Feedback, and Rating', 'error');
      return;
    }

    try {
      // Prepare data for submission
      const submissionData = {
        name: reviewData.name.trim(),
        photo: reviewData.photo,
        feedback: reviewData.feedback.trim(),
        rating: reviewData.rating,
        additionalPhotos: reviewData.additionalPhotos
      };

      // Send data to Google Apps Script
      const response = await fetch(GOOGLE_SCRIPT_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(submissionData)
      });

      const result = await response.json();

      if (result.status === 'success') {
        showSnackbar('Thank you for your review! It has been submitted successfully.');
        handleReviewDialogClose();
      } else {
        throw new Error(result.message);
      }

    } catch (error) {
      console.error('Error submitting review:', error);
      showSnackbar('Failed to submit review. Please try again.', 'error');
    }
  };

  // Custom Scrollbar Styles
  const CustomScrollbarStyles = () => (
    <GlobalStyles styles={{
      '::-webkit-scrollbar': {
        width: '8px',
        height: '8px',
      },
      '::-webkit-scrollbar-track': {
        background: 'rgba(0, 0, 0, 0.1)',
        borderRadius: '10px',
      },
      '::-webkit-scrollbar-thumb': {
        background: 'linear-gradient(135deg, #FF9800 0%, #F57C00 100%)',
        borderRadius: '10px',
        border: '1px solid rgba(255,255,255,0.2)',
      },
      '::-webkit-scrollbar-thumb:hover': {
        background: 'linear-gradient(135deg, #F57C00 0%, #EF6C00 100%)',
      },
      '::-webkit-scrollbar-corner': {
        background: 'transparent',
      },
      'html': {
        scrollbarWidth: 'thin',
        scrollbarColor: '#FF9800 rgba(0, 0, 0, 0.1)',
      },
      '.custom-dialog-scrollbar': {
        scrollbarWidth: 'thin',
        scrollbarColor: '#FF9800 rgba(0, 0, 0, 0.1)',
      },
      '.custom-dialog-scrollbar::-webkit-scrollbar': {
        width: '6px',
      },
      '.custom-dialog-scrollbar::-webkit-scrollbar-track': {
        background: 'rgba(255, 255, 255, 0.05)',
        borderRadius: '3px',
        margin: '4px',
      },
      '.custom-dialog-scrollbar::-webkit-scrollbar-thumb': {
        background: 'linear-gradient(135deg, #FF9800 0%, #F57C00 100%)',
        borderRadius: '3px',
      },
    }} />
  );

 const ReviewDialog = () => (
  <Dialog 
    open={reviewDialogOpen} 
    onClose={handleReviewDialogClose}
    maxWidth="sm"
    fullWidth
    sx={{
      '& .MuiDialog-paper': {
        background: 'linear-gradient(135deg, rgba(0,0,0,0.95) 0%, rgba(50,50,50,0.98) 100%)',
        color: 'white',
        borderRadius: '16px',
        backdropFilter: 'blur(10px)',
        maxHeight: '90vh',
        display: 'flex',
        flexDirection: 'column',
      }
    }}
  >
    <DialogTitle sx={{ 
      borderBottom: '1px solid rgba(255,255,255,0.1)',
      padding: '20px 24px',
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      flexShrink: 0,
    }}>
      <Typography variant="h6" sx={{ fontFamily: "'AlanSans', sans-serif", fontWeight: 600 }}>
        Add Your Review
      </Typography>
      <IconButton 
        onClick={handleReviewDialogClose} 
        sx={{ color: 'white' }}
      >
        <Close />
      </IconButton>
    </DialogTitle>

    <DialogContent 
      sx={{ 
        padding: '20px 24px',
        flex: 1,
        overflow: 'auto',
        '&::-webkit-scrollbar': {
          width: '6px',
        },
        '&::-webkit-scrollbar-track': {
          background: 'rgba(255, 255, 255, 0.05)',
          borderRadius: '3px',
          margin: '4px',
        },
        '&::-webkit-scrollbar-thumb': {
          background: 'linear-gradient(135deg, #FF9800 0%, #F57C00 100%)',
          borderRadius: '3px',
        },
        scrollbarWidth: 'thin',
        scrollbarColor: '#FF9800 rgba(0, 0, 0, 0.1)',
      }}
    >
      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
        {/* Name Field - Mandatory */}
        <Box>
          <Typography variant="body1" sx={{ mb: 1, fontFamily: "'AlanSans', sans-serif" }}>
            Name <span style={{ color: '#FF9800' }}>*</span>
          </Typography>
          <TextField
            fullWidth
            variant="outlined"
            value={reviewData.name}
            onChange={(e) => handleInputChange('name', e.target.value)}
            sx={{
              '& .MuiOutlinedInput-root': {
                color: 'white',
                '& fieldset': {
                  borderColor: 'rgba(255,255,255,0.3)',
                },
                '&:hover fieldset': {
                  borderColor: 'rgba(255,255,255,0.5)',
                },
                '&.Mui-focused fieldset': {
                  borderColor: '#FF9800',
                },
              },
            }}
          />
        </Box>

        {/* Add Your Photo - Optional */}
        <Box>
          <Typography variant="body1" sx={{ mb: 1, fontFamily: "'AlanSans', sans-serif" }}>
            Add Your Photo (Optional)
          </Typography>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
            {reviewData.photo ? (
              <Avatar src={reviewData.photo} sx={{ width: 60, height: 60 }} />
            ) : (
              <Avatar sx={{ width: 60, height: 60, bgcolor: 'rgba(255,255,255,0.1)' }} />
            )}
            <Button
              variant="outlined"
              component="label"
              sx={{
                color: 'white',
                borderColor: 'rgba(255,255,255,0.3)',
                '&:hover': {
                  borderColor: '#FF9800',
                  backgroundColor: 'rgba(255,152,0,0.1)',
                },
              }}
            >
              Upload Photo
              <input
                type="file"
                hidden
                accept="image/*"
                onChange={(e) => handlePhotoUpload(e, 'photo')}
              />
            </Button>
          </Box>
        </Box>

        {/* Feedback on Training - Mandatory */}
        <Box>
          <Typography variant="body1" sx={{ mb: 1, fontFamily: "'AlanSans', sans-serif" }}>
            Feedback on Training <span style={{ color: '#FF9800' }}>*</span>
          </Typography>
          <TextField
            fullWidth
            multiline
            rows={4}
            variant="outlined"
            value={reviewData.feedback}
            onChange={(e) => handleInputChange('feedback', e.target.value)}
            sx={{
              '& .MuiOutlinedInput-root': {
                color: 'white',
                '& fieldset': {
                  borderColor: 'rgba(255,255,255,0.3)',
                },
                '&:hover fieldset': {
                  borderColor: 'rgba(255,255,255,0.5)',
                },
                '&.Mui-focused fieldset': {
                  borderColor: '#FF9800',
                },
              },
            }}
          />
        </Box>

        {/* Overall Rating - Mandatory */}
        <Box>
          <Typography variant="body1" sx={{ mb: 1, fontFamily: "'AlanSans', sans-serif" }}>
            Overall Rating <span style={{ color: '#FF9800' }}>*</span>
          </Typography>
          <Rating
            value={reviewData.rating}
            onChange={(event, newValue) => handleInputChange('rating', newValue)}
            size="large"
            sx={{
              '& .MuiRating-icon': {
                color: 'rgba(255,255,255,0.3)',
              },
              '& .MuiRating-iconFilled': {
                color: '#FF9800',
              },
              '& .MuiRating-iconHover': {
                color: '#FFB74D',
              },
            }}
          />
        </Box>

        {/* Additional Photos - Optional */}
        <Box>
          <Typography variant="body1" sx={{ mb: 1, fontFamily: "'AlanSans', sans-serif" }}>
            Any Photos Taken (Optional)
          </Typography>
          <Button
            variant="outlined"
            component="label"
            sx={{
              color: 'white',
              borderColor: 'rgba(255,255,255,0.3)',
              '&:hover': {
                borderColor: '#FF9800',
                backgroundColor: 'rgba(255,152,0,0.1)',
              },
            }}
          >
            Upload Photos
            <input
              type="file"
              hidden
              multiple
              accept="image/*"
              onChange={handleAdditionalPhotosUpload}
            />
          </Button>
          {reviewData.additionalPhotos.length > 0 && (
            <Box sx={{ 
              display: 'flex', 
              gap: 1, 
              mt: 2, 
              flexWrap: 'wrap',
              maxHeight: '120px',
              overflowY: 'auto',
              padding: '4px',
              '&::-webkit-scrollbar': {
                width: '4px',
              },
              '&::-webkit-scrollbar-track': {
                background: 'rgba(255, 255, 255, 0.05)',
                borderRadius: '2px',
              },
              '&::-webkit-scrollbar-thumb': {
                background: 'linear-gradient(135deg, #FF9800 0%, #F57C00 100%)',
                borderRadius: '2px',
              },
              scrollbarWidth: 'thin',
            }}>
              {reviewData.additionalPhotos.map((photo, index) => (
                <Avatar key={index} src={photo} sx={{ width: 60, height: 60 }} />
              ))}
            </Box>
          )}
        </Box>
      </Box>
    </DialogContent>

    <DialogActions sx={{ 
      padding: '16px 24px 20px',
      borderTop: '1px solid rgba(255,255,255,0.1)',
      flexShrink: 0,
    }}>
      <Button 
        onClick={handleReviewDialogClose}
        sx={{
          color: 'rgba(255,255,255,0.7)',
          '&:hover': {
            color: 'white',
            backgroundColor: 'rgba(255,255,255,0.1)',
          },
        }}
      >
        Cancel
      </Button>
      <Button 
        onClick={handleSubmitReview}
        variant="contained"
        sx={{
          background: 'linear-gradient(135deg, #FF9800 0%, #F57C00 100%)',
          '&:hover': {
            background: 'linear-gradient(135deg, #F57C00 0%, #EF6C00 100%)',
          },
        }}
      >
        Submit Review
      </Button>
    </DialogActions>
  </Dialog>
);

  const drawerContent = (
    <Box
      sx={{
        width: 280,
        height: "100%",
        background: "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)",
        backdropFilter: "blur(10px)",
        color: "white",
        padding: 2,
        display: 'flex',
        flexDirection: 'column',
        overflow: 'hidden',
      }}
    >
      <Box sx={{ 
        display: "flex", 
        justifyContent: "space-between", 
        alignItems: "center", 
        mb: 3,
        flexShrink: 0,
      }}>
        <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
          <FaTableTennis className="text-orange-500 text-2xl" />
          <span className="font-in font-bold text-white">BT's TT Academy</span>
        </Box>
        <IconButton onClick={handleDrawerToggle} sx={{ color: "white" }}>
          <Close />
        </IconButton>
      </Box>

      <List sx={{ flex: 1, overflowY: 'auto', className: 'custom-dialog-scrollbar' }}>
        {menuItems.map((item, index) => (
          <ListItem
            key={item}
            component="button"
            onClick={() => handleMobileMenuItemClick(index)}
            sx={{
              border: currentTab === index ? "1px solid #FF9800" : "1px solid rgba(255,255,255,0.1)",
              borderRadius: "8px",
              marginBottom: 1,
              background: currentTab === index ? "rgba(255,165,0,0.2)" : "rgba(255,255,255,0.05)",
              backdropFilter: "blur(10px)",
              transition: "all 0.3s ease",
              "&:hover": {
                background: "rgba(255,165,0,0.2)",
                borderColor: "rgba(255,165,0,0.5)",
              },
            }}
          >
            <ListItemText 
              primary={item} 
              sx={{ 
                color: currentTab === index ? "#FF9800" : "white",
                "& .MuiListItemText-primary": {
                  fontFamily: "'AlanSans', sans-serif",
                  fontWeight: currentTab === index ? 600 : 500,
                }
              }} 
            />
          </ListItem>
        ))}
      </List>

      <Box sx={{ padding: 2, flexShrink: 0 }}>
        <CustomButton 
          rating 
          size="small" 
          text="Add Review" 
          fullWidth
          onClick={handleReviewDialogOpen}
        />
      </Box>
    </Box>
  );

  return (
    <>
      <CustomScrollbarStyles />
      
      <div 
        position="static" 
        sx={{ 
          background: "transparent", 
          boxShadow: "none",
          backdropFilter: "blur(10px)",
          background: "rgba(0,0,0,0.1)",
        }}
      >
        <Toolbar sx={{ justifyContent: "space-between", padding: "8px 0" }}>
          {/* Logo */}
          <Box sx={{ display: "flex", alignItems: "center" }}>
            <FaTableTennis className="text-white text-3xl" />
          </Box>

          {/* Desktop Menu with Tabs */}
          <Box sx={{ display: { xs: "none", md: "flex" }, alignItems: "center", gap: 2 }}>
            <Box 
              sx={{ 
                background: "rgba(0,0,0,0.1)",
                backdropFilter: "blur(10px)",
                borderRadius: "25px",
                border: "1px solid rgba(255,255,255,0.1)",
                padding: "4px",
              }}
            >
              <Tabs
                value={currentTab}
                onChange={handleTabChange}
                sx={{
                  minHeight: "40px",
                  "& .MuiTabs-indicator": {
                    backgroundColor: "#f97316",
                    height: "100%",
                    borderRadius: "20px",
                    boxShadow: "0 2px 8px rgba(255,152,0,0.3)",
                  },
                  "& .MuiTab-root": {
                    color: "rgba(255,255,255,0.7)",
                    fontFamily: "'AlanSans', sans-serif",
                    fontWeight: 500,
                    fontSize: "14px",
                    textTransform: "none",
                    minHeight: "32px",
                    margin: "0 2px",
                    minWidth: "auto",
                    zIndex: 1,
                    transition: "all 0.3s ease",
                    "&.Mui-selected": {
                      color: "white",
                      fontWeight: 600,
                    },
                    "&:hover": {
                      color: "#E2DBD1",
                    },
                  },
                }}
              >
                {menuItems.map((item) => (
                  <Tab key={item} label={item} />
                ))}
              </Tabs>
            </Box>

            <CustomButton 
              rating 
              size="small" 
              text="Add Review" 
              onClick={handleReviewDialogOpen}
            />
          </Box>

          {/* Mobile Menu Button */}
          <IconButton
            sx={{ 
              display: { xs: "flex", md: "none" },
              color: "white",
              background: "rgba(0,0,0,0.1)",
              backdropFilter: "blur(10px)",
              border: "1px solid rgba(255,255,255,0.1)",
              "&:hover": {
                background: "rgba(255,165,0,0.2)",
              },
            }}
            onClick={handleDrawerToggle}
          >
            <GiHamburgerMenu />
          </IconButton>
        </Toolbar>
      </div>

      {/* Mobile Drawer */}
      <Drawer
        variant="temporary"
        anchor="right"
        open={drawerOpen}
        onClose={handleDrawerToggle}
        ModalProps={{
          keepMounted: true,
        }}
        sx={{
          display: { xs: "block", md: "none" },
          "& .MuiDrawer-paper": {
            boxSizing: "border-box",
            width: 280,
            border: "none",
            background: "transparent",
          },
        }}
      >
        {drawerContent}
      </Drawer>

      {/* Review Dialog */}
      <ReviewDialog />

      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert 
          onClose={() => setSnackbar({ ...snackbar, open: false })} 
          severity={snackbar.severity}
          sx={{ width: '100%' }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </>
  );
};

export default NavBar;
